def grip_pose(pos, alpha_deg, theta_deg, option="B"):
    a = np.radians(alpha_deg); t = np.radians(theta_deg)
    h = np.array([np.cos(a), np.sin(a), 0.0])
    approach = np.cos(t)*np.array([0,0,-1.0]) + np.sin(t)*h
    closing = np.array([-np.sin(a), np.cos(a), 0.0])
    if option == "B": closing = -closing
    return rh.pose_from_axes(pos, approach, closing)
